import { Text, Container } from "@earendil-works/pi-tui";

let turns = 0;

export default function refreshExt(pi) {
  pi.on("turn_end", () => {
    turns += 1;
  });
  pi.on("session_start", (_e, ctx) => {
    if (typeof ctx.ui?.setFooter !== "function") return;
    ctx.ui.setFooter((tui, theme) => ({
      render(width) {
        const box = new Container();
        box.addChild(new Text(theme.fg("dim", `K4 n=${turns} w=${width}`), 1, 0));
        return [theme.fg("dim", `K4 n=${turns} w=${width}`)];
      },
      invalidate() {},
    }));
  });
}
